// Secure Password Hashing & Timing-Safe Authentication Service
import argon2 from 'argon2';
import crypto from 'node:crypto';

// Dummy hash used to balance latency when account is missing
const DUMMY_HASH = '$argon2id$v=19$m=65536,t=3,p=4$dummy_salt_for_timing$dummy_hash_value';

export class AuthenticationSecurityService {
  // 1. Password Hashing with Argon2id
  static async hashPassword(plainText: string): Promise<string> {
    return await argon2.hash(plainText, {
      type: argon2.argon2id, // Hybrid defense against side-channel & GPU attacks
      memoryCost: 65536,     // 64 MB RAM per hash
      timeCost: 3,           // 3 computational passes
      parallelism: 4         // 4 parallel threads
    });
  }

  // 2. Timing-Safe Authentication Verification (Eliminating User Enumeration)
  static async verifyLoginAttempt(user: { passwordHash: string } | null, candidatePassword: string): Promise<boolean> {
    if (!user) {
      // Execute dummy hash comparison to consume identical CPU cycles
      await argon2.verify(DUMMY_HASH, candidatePassword).catch(() => false);
      return false;
    }

    return await argon2.verify(user.passwordHash, candidatePassword);
  }
}

// Secure Refresh Token Rotation & Family Invalidation in Express
import express, { Request, Response } from 'express';
import crypto from 'node:crypto';
import jwt from 'jsonwebtoken';

const app = express();
const JWT_SECRET = process.env.JWT_SECRET || 'super_secret_jwt_key_at_least_32_chars';

// Refresh Token Record Schema
interface RefreshTokenRecord {
  id: string;
  userId: string;
  tokenFamily: string; // Grouping identifier for reuse detection
  isRevoked: boolean;
  expiresAt: Date;
}

const tokenStore = new Map<string, RefreshTokenRecord>();

export async function rotateRefreshToken(req: Request, res: Response) {
  const incomingToken = req.cookies?.refreshToken;
  if (!incomingToken) return res.status(401).json({ error: 'Missing refresh token' });

  const record = tokenStore.get(incomingToken);

  // THEFT DETECTION: If token does not exist or was already revoked, purge family!
  if (!record || record.isRevoked) {
    if (record) {
      // Invalidate all tokens belonging to this family
      for (const [key, t] of tokenStore.entries()) {
        if (t.tokenFamily === record.tokenFamily) {
          t.isRevoked = true;
        }
      }
    }
    res.clearCookie('refreshToken');
    return res.status(403).json({ error: 'Security alert: Refresh token reuse detected. Session terminated.' });
  }

  // Invalidate current token
  record.isRevoked = true;

  // Generate new Access Token (15 minutes)
  const newAccessToken = jwt.sign({ userId: record.userId }, JWT_SECRET, { expiresIn: '15m' });

  // Generate new Refresh Token within same family (7 days)
  const newRefreshToken = crypto.randomBytes(32).toString('hex');
  tokenStore.set(newRefreshToken, {
    id: crypto.randomUUID(),
    userId: record.userId,
    tokenFamily: record.tokenFamily,
    isRevoked: false,
    expiresAt: new Date(Date.now() + 7 * 86400 * 1000)
  });

  // Set Secure Cookie
  res.cookie('refreshToken', newRefreshToken, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    maxAge: 7 * 86400 * 1000,
    path: '/api/auth/refresh' // Restrict cookie transmission strictly to refresh endpoint!
  });

  return res.json({ accessToken: newAccessToken });
}

// Secure API Key Generator, Hasher & Verification Middleware
import crypto from 'node:crypto';

export interface GeneratedApiKey {
  rawKey: string;     // Shown once to developer
  keyHash: string;    // Stored in database
  displayPrefix: string;
}

export class ApiKeyService {
  // 1. Generate Secure Prefixed API Key
  static generateKey(env = 'live'): GeneratedApiKey {
    const prefix = `sk_${env}_`;
    const randomEntropy = crypto.randomBytes(24).toString('base64url'); // 32 random characters
    const rawKey = `${prefix}${randomEntropy}`;

    // Compute SHA-256 hash for database storage
    const keyHash = crypto.createHash('sha256').update(rawKey).digest('hex');
    const displayPrefix = rawKey.substring(0, 12) + '...';

    return { rawKey, keyHash, displayPrefix };
  }

  // 2. Constant-Time API Key Verification
  static verifyApiKey(rawClientKey: string, storedHash: string): boolean {
    const computedHash = crypto.createHash('sha256').update(rawClientKey).digest('hex');

    const bufComputed = Buffer.from(computedHash, 'utf-8');
    const bufStored = Buffer.from(storedHash, 'utf-8');

    if (bufComputed.length !== bufStored.length) return false;
    return crypto.timingSafeEqual(bufComputed, bufStored);
  }
}

// Reusable Express RBAC & Ownership Authorization Middleware
export function requireRoles(...allowedRoles) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ success: false, error: 'Unauthenticated' });
    }
    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ success: false, error: 'Forbidden: Insufficient permissions' });
    }
    next();
  };
}

export function requireOwnership(getOwnerIdFn) {
  return async (req, res, next) => {
    const ownerId = await getOwnerIdFn(req);
    if (req.user.role !== 'admin' && req.user.id !== ownerId) {
      return res.status(403).json({ success: false, error: 'Forbidden: You do not own this resource' });
    }
    next();
  };
}

// Safe multi-tenant service method avoiding IDOR
export class InvoiceService {
  constructor(invoiceRepository) {
    this.repo = invoiceRepository;
  }

  async deleteInvoice(invoiceId, user) {
    // Query MUST include organizationId constraint
    const deleted = await this.repo.deleteByIdAndOrg(invoiceId, user.organizationId);
    if (!deleted) {
      // Return 404 rather than 403 to prevent ID harvesting/enumeration
      const err = new Error('Invoice not found');
      err.statusCode = 404;
      throw err;
    }
    return { success: true };
  }
}

// Comprehensive Express CORS Architectures (7 Production Patterns)
import express from 'express';
import cors from 'cors';

const app = express();
app.set('trust proxy', 1);

// ============================================================================
// PATTERN 1: Public Open API (Zero Credentials, Wildcard Allowed)
// ============================================================================
export const publicApiCors = cors({
  origin: '*',
  methods: ['GET', 'HEAD', 'OPTIONS'],
  allowedHeaders: ['Content-Type'],
  maxAge: 86400 // Cache preflight for 24 hours
});

// ============================================================================
// PATTERN 2: Single Dedicated Frontend Origin
// ============================================================================
export const singleOriginCors = cors({
  origin: 'https://app.chrona.io',
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400
});

// ============================================================================
// PATTERN 3: Environment-Specific Small Allowlist (Dev + Prod)
// ============================================================================
const ALLOWED_ORIGINS = new Set([
  'http://localhost:5173',          // Vite local dev
  'http://localhost:3000',          // Next.js local dev
  'https://staging.chrona.io',      // Staging
  'https://app.chrona.io'           // Production
]);

export const allowlistCors = cors({
  origin: (origin, callback) => {
    // !origin allows non-browser clients (mobile apps, server-to-server, curl)
    if (!origin || ALLOWED_ORIGINS.has(origin)) {
      callback(null, true);
    } else {
      callback(new Error(`Origin ${origin} rejected by CORS policy`));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With', 'Idempotency-Key'],
  exposedHeaders: ['X-Total-Count', 'X-RateLimit-Remaining'],
  maxAge: 86400
});

// ============================================================================
// PATTERN 4: Cookie-Based Authentication with Credentials & Vary: Origin
// ============================================================================
export const cookieAuthCors = (req, res, next) => {
  const origin = req.headers.origin;
  if (ALLOWED_ORIGINS.has(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
    res.setHeader('Access-Control-Allow-Credentials', 'true');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
    res.setHeader('Access-Control-Max-Age', '86400');
    // CRITICAL: Prevent CDN cache poisoning across multiple clients
    res.setHeader('Vary', 'Origin');
  }

  // Handle explicit preflight
  if (req.method === 'OPTIONS') {
    return res.sendStatus(204);
  }
  next();
};

// ============================================================================
// PATTERN 5: Rejected Origin with Clean JSON Response
// ============================================================================
export const secureDynamicCors = (req, res, next) => {
  const origin = req.headers.origin;
  if (origin && !ALLOWED_ORIGINS.has(origin)) {
    return res.status(403).json({
      error: 'ForbiddenOrigin',
      message: `Cross-Origin request from origin '${origin}' is not permitted.`
    });
  }
  next();
};

// ============================================================================
// PATTERN 6: Explicit Preflight Route Handling
// ============================================================================
app.options('*', cors({
  origin: Array.from(ALLOWED_ORIGINS),
  credentials: true,
  maxAge: 86400
}));

// ============================================================================
// PATTERN 7: Full Production Application Mount
// ============================================================================
app.use(allowlistCors);
app.use(express.json({ limit: '100kb' }));

app.get('/api/v1/profile', (req, res) => {
  res.json({ user: 'sarah_staff_eng', role: 'architect' });
});

app.listen(4000, () => {
  console.log('Secure CORS API server running on port 4000');
});

// Production Helmet 8+ Configuration for Express.js
import express from 'express';
import helmet from 'helmet';
import crypto from 'node:crypto';

const app = express();
const isProd = process.env.NODE_ENV === 'production';

// Step 1: Trust Reverse Proxy (AWS ALB, Cloudflare, Nginx)
app.set('trust proxy', 1);

// Step 2: Per-Request Cryptographic Nonce Generator for Dynamic Scripts
app.use((req, res, next) => {
  res.locals.cspNonce = crypto.randomBytes(16).toString('base64');
  next();
});

// Step 3: Modern Helmet 8 Configuration
app.use((req, res, next) => {
  helmet({
    // Content-Security-Policy
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        scriptSrc: [
          "'self'",
          // In dev allow unsafe-eval for Vite HMR; in prod require strict nonce
          isProd ? `'nonce-${res.locals.cspNonce}'` : "'unsafe-eval'",
          'https://js.stripe.com', // Third-party trusted provider
          'https://apis.google.com'
        ],
        styleSrc: ["'self'", "'unsafe-inline'", 'https://fonts.googleapis.com'],
        fontSrc: ["'self'", 'https://fonts.gstatic.com', 'data:'],
        imgSrc: ["'self'", 'data:', 'https:', 'blob:'],
        connectSrc: [
          "'self'",
          'https://api.chrona.io',
          'https://api.stripe.com',
          // WebSocket connection for local dev HMR
          !isProd && 'ws://localhost:*'
        ].filter(Boolean),
        frameSrc: ["'self'", 'https://js.stripe.com'],
        frameAncestors: ["'none'"], // Prevent clickjacking
        objectSrc: ["'none'"],      // Block legacy plugins
        baseUri: ["'self'"],
        formAction: ["'self'"],
        upgradeInsecureRequests: isProd ? [] : null // Force HTTPS in prod
      }
    },

    // Strict-Transport-Security (Only in Production with valid TLS)
    strictTransportSecurity: isProd ? {
      maxAge: 31536000,           // 1 Year
      includeSubDomains: true,    // Apply to *.chrona.io
      preload: true               // Candidate for HSTS preload list
    } : false,                    // Disable on localhost!

    // Prevent MIME-Type Sniffing
    xContentTypeOptions: true,

    // Referrer Policy
    referrerPolicy: {
      policy: 'strict-origin-when-cross-origin'
    },

    // Frame Protection (Fallback for legacy browsers)
    xFrameOptions: { action: 'deny' },

    // Cross-Origin Isolation Policies
    crossOriginOpenerPolicy: { policy: 'same-origin' },
    crossOriginResourcePolicy: { policy: 'same-origin' },
    crossOriginEmbedderPolicy: false, // Set to 'require-corp' if using SharedArrayBuffer

    // Hide X-Powered-By: Express
    hidePoweredBy: true,

    // X-DNS-Prefetch-Control
    xXssProtection: false // Deprecated in modern browsers; CSP takes precedence
  })(req, res, next);
});

app.get('/', (req, res) => {
  // Pass nonce into HTML rendering templates if using SSR
  res.send(`
    <!DOCTYPE html>
    <html>
      <head>
        <title>Secure Helmet Application</title>
      </head>
      <body>
        <h1>Protected by Helmet 8+</h1>
        <script nonce="${res.locals.cspNonce}">
          console.log('Authorized script executed with cryptographic nonce');
        </script>
      </body>
    </html>
  `);
});

export default app;

