// Complete OWASP Hardening Demonstration: Safe SSRF & NoSQL Injection Defense
import express from 'express';
import dns from 'node:dns/promises';
import net from 'node:net';
import ipaddr from 'ipaddr.js'; // npm i ipaddr.js
import { z } from 'zod';

const app = express();
app.use(express.json());

// ============================================================================
// DEFENSE 1: SSRF Safe Fetcher with Private IP Blocking & DNS Rebinding Check
// ============================================================================
export async function safeFetchUrl(rawUrl) {
  const parsed = new URL(rawUrl);
  if (!['http:', 'https:'].includes(parsed.protocol)) {
    throw new Error('Unsupported protocol');
  }

  // Step 1: Resolve DNS to concrete IPv4 addresses
  const addresses = await dns.resolve4(parsed.hostname);
  if (!addresses || addresses.length === 0) {
    throw new Error('Could not resolve hostname');
  }

  // Step 2: Validate that NONE of the resolved IPs are in private/internal ranges
  for (const ip of addresses) {
    const addr = ipaddr.parse(ip);
    const range = addr.range(); // 'loopback', 'private', 'linkLocal', etc.
    if (['loopback', 'private', 'linkLocal', 'carrierGradeNat'].includes(range)) {
      throw new Error(`Forbidden SSRF destination IP: ${ip} (range: ${range})`);
    }
    // Block AWS/Cloud Metadata IP specifically
    if (ip === '169.254.169.254') {
      throw new Error('Cloud metadata endpoint access strictly blocked');
    }
  }

  // Step 3: Fetch directly using the verified target
  const response = await fetch(parsed.toString(), {
    redirect: 'error', // Crucial: Do not blindly follow redirects to internal network!
    signal: AbortSignal.timeout(5000)
  });

  return await response.text();
}

// ============================================================================
// DEFENSE 2: Strict Zod Input Validation Defeating NoSQL Operator Injections
// ============================================================================
const safeUserLoginSchema = z.object({
  email: z.string().email().max(255),
  // Enforces string primitive: completely rejects JSON objects like { "$gt": "" }
  password: z.string().min(8).max(128)
});

app.post('/api/auth/login', async (req, res) => {
  const parsed = safeUserLoginSchema.safeParse(req.body);
  if (!parsed.success) {
    return res.status(400).json({ error: 'ValidationFailed', details: parsed.error.issues });
  }

  const { email, password } = parsed.data;
  // Safely query database using pure strings
  res.json({ status: 'Input safely validated against NoSQL injection vectors' });
});

export default app;

// Secure File Upload & Path Traversal Defense Implementation
import express from 'express';
import path from 'node:path';
import fs from 'node:fs/promises';
import crypto from 'node:crypto';
import { fileTypeFromBuffer } from 'file-type'; // npm i file-type

const app = express();
const UPLOAD_ROOT = path.resolve(process.cwd(), 'secure_storage');

// ============================================================================
// DEFENSE 1: Safe Path Traversal Validator
// ============================================================================
export function resolveSafePath(baseDir, requestedRelativePath) {
  const safeBase = path.resolve(baseDir);
  const resolvedTarget = path.resolve(safeBase, requestedRelativePath);

  // Strict check: must reside inside safeBase
  if (!resolvedTarget.startsWith(safeBase + path.sep)) {
    throw new Error('Path traversal attempt detected');
  }

  return resolvedTarget;
}

// ============================================================================
// DEFENSE 2: File Upload Magic Byte Inspection & UUID Sanitization
// ============================================================================
const ALLOWED_MIME_TYPES = new Set(['image/jpeg', 'image/png', 'image/webp']);

export async function processUploadedFileBuffer(fileBuffer, originalFilename) {
  // Step 1: Inspect True Binary Magic Bytes (Do not trust user Content-Type!)
  const detectedType = await fileTypeFromBuffer(fileBuffer);

  if (!detectedType || !ALLOWED_MIME_TYPES.has(detectedType.mime)) {
    throw new Error(`Invalid file content. Detected: ${detectedType?.mime || 'unknown'}`);
  }

  // Step 2: Generate Safe Random UUID Filename with verified extension
  const safeFilename = `${crypto.randomUUID()}.${detectedType.ext}`;
  const destinationPath = resolveSafePath(UPLOAD_ROOT, safeFilename);

  // Step 3: Write safely to disk or stream to S3
  await fs.writeFile(destinationPath, fileBuffer);

  return { safeFilename, mime: detectedType.mime };
}

app.get('/api/files/:filename', async (req, res, next) => {
  try {
    const safePath = resolveSafePath(UPLOAD_ROOT, req.params.filename);
    res.sendFile(safePath);
  } catch (err) {
    res.status(403).json({ error: 'Access denied: invalid file path' });
  }
});

export default app;

// Production Application Hardening: Idempotency, Timing-Safe Checks & Replay Defense
import express from 'express';
import crypto from 'node:crypto';
import rateLimit from 'express-rate-limit';

const app = express();
app.set('trust proxy', 1);

// Step 1: Memory Exhaustion DoS Protection
app.use(express.json({ limit: '100kb' }));

// Step 2: Production Rate Limiting
export const authRateLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 10,                   // 10 requests per IP per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'TooManyRequests', message: 'Rate limit exceeded. Please try again later.' }
});

// Step 3: Constant-Time Token Comparison Defeating Timing Attacks
export function timingSafeCompare(secretA, secretB) {
  const bufA = Buffer.from(secretA, 'utf-8');
  const bufB = Buffer.from(secretB, 'utf-8');

  // Length mismatch check in constant time
  if (bufA.length !== bufB.length) {
    // Compare dummy buffer to maintain constant timing
    crypto.timingSafeEqual(bufA, bufA);
    return false;
  }

  return crypto.timingSafeEqual(bufA, bufB);
}

// Step 4: Replay Attack Defense Middleware (Timestamp + Nonce)
const simulatedRedisNonces = new Set();

export function replayAttackDefense(req, res, next) {
  const timestamp = parseInt(req.headers['x-timestamp'], 10);
  const nonce = req.headers['x-nonce'];

  if (!timestamp || !nonce) {
    return res.status(400).json({ error: 'Missing replay protection headers' });
  }

  // Reject requests older than 5 minutes or in future
  const now = Date.now();
  if (Math.abs(now - timestamp) > 5 * 60 * 1000) {
    return res.status(401).json({ error: 'Request expired: timestamp drift too large' });
  }

  // Check Nonce uniqueness (In prod use Redis SET nonce:id 1 EX 300 NX)
  if (simulatedRedisNonces.has(nonce)) {
    return res.status(409).json({ error: 'Replay detected: duplicate nonce' });
  }

  simulatedRedisNonces.add(nonce);
  next();
}

app.post('/api/transactions', replayAttackDefense, (req, res) => {
  res.json({ success: true, transactionId: crypto.randomUUID() });
});

export default app;

// Production Webhook Signature Verification Middleware
import express, { Request, Response } from 'express';
import crypto from 'node:crypto';

const app = express();

// Step 1: Capture Raw Body Buffer exclusively for Webhook Verification
app.use(express.json({
  verify: (req: any, res, buf) => {
    // Attach exact unparsed binary buffer
    req.rawBody = buf;
  }
}));

const WEBHOOK_SIGNING_SECRET = process.env.WEBHOOK_SECRET || 'whsec_test_secret_32_bytes_long';

// Step 2: Verification Middleware Function
export function verifyHmacWebhookSignature(req: any, res: Response, next: express.NextFunction) {
  const signatureHeader = req.headers['x-hub-signature-256'] as string;

  if (!signatureHeader || !req.rawBody) {
    return res.status(400).json({ error: 'Missing webhook signature or raw body buffer' });
  }

  // Compute expected HMAC-SHA256 signature from raw Buffer
  const computedSignature = 'sha256=' + crypto
    .createHmac('sha256', WEBHOOK_SIGNING_SECRET)
    .update(req.rawBody)
    .digest('hex');

  const bufExpected = Buffer.from(computedSignature, 'utf-8');
  const bufReceived = Buffer.from(signatureHeader, 'utf-8');

  // Constant-time comparison
  if (bufExpected.length !== bufReceived.length || !crypto.timingSafeEqual(bufExpected, bufReceived)) {
    console.error('🚨 Webhook signature mismatch! Possible spoofing attempt.');
    return res.status(401).json({ error: 'Invalid webhook signature' });
  }

  next();
}

app.post('/api/webhooks/payments', verifyHmacWebhookSignature, (req, res) => {
  // Signature verified! Acknowledge immediately with 200 OK
  res.status(200).json({ received: true });
});

// Razorpay Payment Verification & Stripe Webhook Reconciliation
import crypto from 'node:crypto';

// ============================================================================
// 1. Razorpay Server-Side Signature Verification
// ============================================================================
export interface RazorpayVerificationInput {
  orderId: string;
  paymentId: string;
  signature: string;
}

export function verifyRazorpaySignature(
  input: RazorpayVerificationInput,
  razorpaySecret: string
): boolean {
  const { orderId, paymentId, signature } = input;

  // Razorpay standard: HMAC-SHA256 of "order_id|payment_id"
  const payload = `${orderId}|${paymentId}`;
  const expectedSignature = crypto
    .createHmac('sha256', razorpaySecret)
    .update(payload)
    .digest('hex');

  const bufExpected = Buffer.from(expectedSignature, 'utf-8');
  const bufReceived = Buffer.from(signature, 'utf-8');

  if (bufExpected.length !== bufReceived.length) return false;
  return crypto.timingSafeEqual(bufExpected, bufReceived);
}

// ============================================================================
// 2. Stripe Checkout Fulfillment Webhook Handler
// ============================================================================
export async function handleStripeCheckoutCompleted(event: any, orderService: any) {
  if (event.type !== 'checkout.session.completed') return;

  const session = event.data.object;
  const orderId = session.metadata?.orderId;
  const paymentIntentId = session.payment_intent;

  if (!orderId) {
    throw new Error('Missing orderId in session metadata');
  }

  // Fulfill order idempotently
  await orderService.markOrderAsPaid({
    orderId,
    paymentIntentId,
    amountTotalCents: session.amount_total
  });
}

// Resilient Payment Processing with Idempotency & Transactional Outbox
import { dbPool } from './mysql';
import crypto from 'node:crypto';

export class ResilientPaymentProcessor {
  // Idempotent Order Charge Execution
  async processPayment(orderId: string, amountCents: number, externalPaymentGateway: any) {
    const idempotencyKey = `idem_order_${orderId}`;

    try {
      // Step 1: Call Payment Gateway with Deterministic Idempotency Key
      const charge = await externalPaymentGateway.createCharge({
        amount: amountCents,
        currency: 'usd',
        idempotencyKey // Provider guarantees single charge on retries!
      });

      // Step 2: Atomic Transactional Outbox Pattern
      await this.persistOrderAndOutboxEvent(orderId, charge.id, amountCents);

      return { status: 'SUCCESS', chargeId: charge.id };
    } catch (err: any) {
      if (err.code === 'ETIMEDOUT' || err.code === 'ECONNRESET') {
        console.warn(`⚠️ Payment gateway timeout for order ${orderId}. Flagging for reconciliation...`);
        await this.flagForReconciliation(orderId);
        return { status: 'PENDING_RECONCILIATION' };
      }
      throw err;
    }
  }

  // Transactional Outbox: Order Update + Domain Event in 1 ACID Commit
  private async persistOrderAndOutboxEvent(orderId: string, chargeId: string, amountCents: number) {
    const conn = await dbPool.getConnection();
    try {
      await conn.beginTransaction();

      // 1. Update Order State
      await conn.execute(
        `UPDATE orders SET status = 'PAID', payment_id = ?, updated_at = NOW() WHERE id = ? AND status = 'PENDING'`,
        [chargeId, orderId]
      );

      // 2. Insert Outbox Event
      const outboxPayload = JSON.stringify({ orderId, chargeId, amountCents, timestamp: new Date() });
      await conn.execute(
        `INSERT INTO outbox_events (id, aggregate_type, aggregate_id, event_type, payload, status)
         VALUES (?, 'ORDER', ?, 'ORDER_PAID', ?, 'PENDING')`,
        [crypto.randomUUID(), orderId, outboxPayload]
      );

      await conn.commit();
    } catch (err) {
      await conn.rollback();
      throw err;
    } finally {
      conn.release();
    }
  }

  private async flagForReconciliation(orderId: string) {
    await dbPool.execute(
      `UPDATE orders SET status = 'PENDING_RECONCILIATION' WHERE id = ?`,
      [orderId]
    );
  }
}

// Generating AWS S3 Pre-signed URLs for Direct Client Uploads
import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';
import crypto from 'node:crypto';

const s3Client = new S3Client({ region: process.env.AWS_REGION || 'us-east-1' });

export async function generateUploadUrl({ userId, filename, contentType, fileSize }) {
  // 1. Validate file constraints
  const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB
  if (fileSize > MAX_FILE_SIZE) {
    throw new Error('File exceeds maximum allowed size of 10MB');
  }

  const ALLOWED_MIME_TYPES = ['image/jpeg', 'image/png', 'application/pdf'];
  if (!ALLOWED_MIME_TYPES.includes(contentType)) {
    throw new Error('Unsupported file type');
  }

  // 2. Generate secure non-predictable S3 object key
  const fileExt = filename.split('.').pop();
  const s3Key = `users/${userId}/${crypto.randomUUID()}.${fileExt}`;

  // 3. Create Presigned PUT Command
  const command = new PutObjectCommand({
    Bucket: process.env.S3_BUCKET_NAME,
    Key: s3Key,
    ContentType: contentType
  });

  // URL valid for 10 minutes
  const presignedUrl = await getSignedUrl(s3Client, command, { expiresIn: 600 });

  return { presignedUrl, s3Key };
}

// Resilient Outgoing API Client with Circuit Breaker State Machine
export class CircuitBreaker {
  constructor(actionFn, options = { failureThreshold: 3, resetTimeoutMs: 10000 }) {
    this.actionFn = actionFn;
    this.failureThreshold = options.failureThreshold;
    this.resetTimeoutMs = options.resetTimeoutMs;
    this.state = 'CLOSED'; // CLOSED, OPEN, HALF_OPEN
    this.failureCount = 0;
    this.nextAttemptTime = Date.now();
  }

  async execute(...args) {
    if (this.state === 'OPEN') {
      if (Date.now() > this.nextAttemptTime) {
        console.warn('⚡ Circuit Breaker entering HALF_OPEN state. Probing upstream service...');
        this.state = 'HALF_OPEN';
      } else {
        throw new Error('Circuit Breaker is OPEN. Upstream service is temporarily unavailable.');
      }
    }

    try {
      const result = await this.actionFn(...args);
      if (this.state === 'HALF_OPEN') {
        console.log('✅ Upstream service recovered! Closing circuit breaker.');
        this.state = 'CLOSED';
        this.failureCount = 0;
      }
      return result;
    } catch (err) {
      this.failureCount++;
      if (this.state === 'HALF_OPEN' || this.failureCount >= this.failureThreshold) {
        this.state = 'OPEN';
        this.nextAttemptTime = Date.now() + this.resetTimeoutMs;
        console.error(`🚨 Circuit Breaker tripped OPEN! Next probe in ${this.resetTimeoutMs}ms`);
      }
      throw err;
    }
  }
}

